def context():
    try:
        set_training_state(model.modules(), False)
        yield
    finally:
        for module, training_state in original_training_states.items():
            module.training = training_state

return context()

class FreezeTrainingModeContext:
    def __init__(self, model):
        self.model = model
        self.original_training_states = {}

    def __enter__(self):
        for name, module in self.model.named_modules():
            # Store original training state
            self.original_training_states[name] = module.training
            # Set training to False and annotate as a constant
            module.training = False
            torch.jit.annotate(bool, False)

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Restore original training states
        for name, module in self.model.named_modules():
            original_state = self.original_training_states.get(name)
            if original_state is not None:
                module.training = original_state

return FreezeTrainingModeContext(model)

