# Check if the path is an S3 URL
if dir_path.startswith("s3://"):
    return Dir(path=None, url=dir_path)

# Check for project-specific paths
path_parts = dir_path.split("/")
if len(path_parts) > 1:
    prefix = path_parts[1].lower()
    if prefix == "studios":
        return _resolve_studio(dir_path, target_name=path_parts[2], target_id=None)
    elif prefix == "data-connections":
        return _resolve_s3_connections(dir_path)
    elif prefix == "datasets":
        return _resolve_datasets(dir_path)

# If none of the above, return the Dir object with the path as is
return Dir(path=dir_path)
